//! DataList connection actions preserve actual native paint and editor/link state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn datalist_connection_actual_app_pointer_attribute_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-datalist-connection-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}#paint{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#cc2244}#paint.done{background:#2244cc}#paint.removed{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><body><div id=paint>Fallback param</div><datalist id=datalist><option value=one>One</option></datalist><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change metadata</button><div id=destination></div><script>var paint=document.getElementById('paint'),first=paint.firstChild,x=document.createElement('datalist'),round=0;x.setAttribute('title','native');var attr=x.getAttributeNode('title'),list=x.options;document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var focus=document.activeElement;if(round===0)paint.appendChild(x);else if(round===1)paint.insertBefore(x,first);else paint.removeChild(x);if(x.parentNode!==(round===2?null:paint)||x.ownerDocument!==document||x.getAttributeNode('title')!==attr||attr.ownerElement!==x||x.getAttribute('title')!=='native'||x.options!==list||list.length!==0||paint.firstChild!==(round===1?x:first)||paint.textContent!=='Fallback param'||document.activeElement!==focus||document.getElementById('neighbor').value!=='edited neighbor')throw 'actual DataList connection';paint.className=['ready','done','removed'][round];document.title='DataList connection '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(!app.failed,"{}",app.status);assert_eq!(app.document.title,format!("DataList connection {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],[0xcc2244,0x2244cc,0x228844][round]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}

#[test]
fn datalist_connection_actual_app_inert_and_template_pointer_routes(){
 for (factory_index,factory) in ["(new Document()).createElementNS('http://www.w3.org/1999/xhtml','datalist')","(function(){var t=document.createElement('template');t.innerHTML='<datalist></datalist>';return t.content.firstChild;})()"].iter().enumerate(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-datalist-connection-routes-{factory_index}-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}#paint{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#cc2244}#paint.done{background:#2244cc}#paint.removed{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><body><div id=paint>Fallback param</div><datalist id=datalist><option value=one>One</option></datalist><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change metadata</button><div id=destination></div><script>var paint=document.getElementById('paint'),first=paint.firstChild,x=FACTORY,round=0;x.setAttribute('title','native');var attr=x.getAttributeNode('title'),list=x.options;document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var focus=document.activeElement;if(round===0)paint.appendChild(x);else if(round===1)paint.insertBefore(x,first);else paint.removeChild(x);if(x.parentNode!==(round===2?null:paint)||x.ownerDocument!==document||x.getAttributeNode('title')!==attr||attr.ownerElement!==x||x.getAttribute('title')!=='native'||x.options!==list||list.length!==0||paint.firstChild!==(round===1?x:first)||paint.textContent!=='Fallback param'||document.activeElement!==focus||document.getElementById('neighbor').value!=='edited neighbor')throw 'actual DataList connection';paint.className=['ready','done','removed'][round];document.title='DataList connection '+round;round++;};</script>"#.replace("FACTORY",factory)).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(!app.failed,"{}",app.status);assert_eq!(app.document.title,format!("DataList connection {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],[0xcc2244,0x2244cc,0x228844][round]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}
}
